TYPE.TEST:

SetFunctionName("Soa4Mask3()");

{
    Soa4Mask3 s;
    Validate( true );
}

//-----------------------------------------------------------------------

SetFunctionName("Soa4Mask3(const Soa4Mask3&)");

{
    Soa4Mask3 a( mAllTrue );
    Soa4Mask3 b( mAllFalse );

    Validate( IsEqual( mAllTrue, a ) && IsEqual( mAllFalse, b ) );
}

//-----------------------------------------------------------------------

SetFunctionName("operator =(const Soa4Mask3&)");

{
    Soa4Mask3 a = mAllTrue;
    Soa4Mask3 b = mAllFalse;

    Validate( IsEqual( mAllTrue, a ) && IsEqual( mAllFalse, b ) );
}


//-----------------------------------------------------------------------

SetFunctionName("Soa4Mask3(Soa4MaskScalar::InParam s)");

{
    Soa4MaskScalar a = CreateSoa4MaskScalar( true, false, true, false );
    Soa4Mask3 mask( a );

    Validate( IsEqual( mask.x, a ) && IsEqual( mask.y, a ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Soa4Mask3(Soa4MaskScalar::InParam, Soa4MaskScalar::InParam)");

{
    Soa4MaskScalar a = CreateSoa4MaskScalar( true, false, true, false );
    Soa4MaskScalar b = CreateSoa4MaskScalar( false, true, false, true );
    Soa4MaskScalar c = CreateSoa4MaskScalar( true, false, false, true );
    Soa4Mask3 mask( a, b, c );

    Validate( IsEqual( mask.x, a ) && IsEqual( mask.y, b ) && IsEqual( mask.z, c ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Soa4Mask3(VectorIntrinsicInParam, VectorIntrinsicInParam, VectorIntrinsicInParam)");

{
    Soa4MaskScalar a = CreateSoa4MaskScalar( true, false, true, false );
    Soa4MaskScalar b = CreateSoa4MaskScalar( false, true, false, true );
    Soa4MaskScalar c = CreateSoa4MaskScalar( true, false, false, true );

    Soa4Mask3 mask( a.mV, b.mV, c.mV );

    Validate( IsEqual( mask.x, a ) && IsEqual( mask.y, b ) && IsEqual( mask.z, c ) );
}


SetFunctionName("X() const");

{
    Soa4Mask3 a( mAllTrue );
    const Soa4MaskScalar& x( a.X() );

    Validate( IsEqual( x, a.x ) );
}

//-----------------------------------------------------------------------

SetFunctionName("X()");

{
    Soa4Mask3 a( mAllTrue );
    Soa4MaskScalar falseMask = CreateSoa4MaskScalar( false, false, false, false );
    a.X() = falseMask;

    Validate( IsEqual( a.x, falseMask ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Y() const");

{
    Soa4Mask3 a( mAllFalse );
    const Soa4MaskScalar& y( a.Y() );

    Validate( IsEqual( y, a.y ) );           
}

//-----------------------------------------------------------------------

SetFunctionName("Y()");

{
    Soa4Mask3 a( mAllTrue );
    Soa4MaskScalar falseMask = CreateSoa4MaskScalar( false, false, false, false );
    a.Y() = falseMask;

    Validate( IsEqual( a.y, falseMask ) );
    }

//-----------------------------------------------------------------------

SetFunctionName("Z() const");

{
    Soa4Mask3 a( mAllFalse );
    const Soa4MaskScalar& z( a.Z() );

    Validate( IsEqual( z, a.z ) );           
}

//-----------------------------------------------------------------------

SetFunctionName("Z()");

{
    Soa4Mask3 a( mAllTrue );
    Soa4MaskScalar falseMask = CreateSoa4MaskScalar( false, false, false, false );
    a.Z() = falseMask;

    Validate( IsEqual( a.z, falseMask ) );
}


SetFunctionName("Not");

{
    Soa4Mask3 a = Not( mAllTrue );
    Validate( IsEqual( a, mAllFalse ) );

    Soa4Mask3 b = Not( mMixed );
    Validate( IsEqual( b.x, mMixed.y ) && IsEqual( b.y, mMixed.x ) );
}

//-----------------------------------------------------------------------

SetFunctionName("And");

{
    Soa4Mask3 a( mMixed.x, mMixed.x, mMixed.x );
    Soa4Mask3 res = And( a, a );
    Validate( IsEqual( res, a ) );

    Soa4Mask3 b = And( mMixed, mAllFalse );
    Validate( IsEqual( b, mAllFalse ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Or");

{
    Soa4Mask3 a = Or( mAllFalse, mAllFalse );
    Validate( IsEqual( a, mAllFalse ) );

    a = Or( a, mMixed );
    Validate( IsEqual( a, mMixed ) );

    a = Or( a, mAllTrue );
    Validate( IsEqual( a, mAllTrue ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Xor");
{
    Soa4Mask3 a = mMixed;

    Soa4Mask3 res = Xor( a, a );
    Validate( IsEqual( res, mAllFalse ) );

    res = Xor( mAllTrue, mAllFalse );
    Validate( IsEqual( res, mAllTrue ) );
}

//-----------------------------------------------------------------------
SetFunctionName("CompEqual");

{
    Soa4Mask3 a( mMixed.y, mMixed.x, CreateSoa4MaskScalar( true, false, false, true ) );
    Soa4Mask3 res = CompEqual( a, mMixed );
    Validate( IsEqual( res, mAllFalse ) );

    a = Soa4Mask3( mMixed );
    res = CompEqual( a, mMixed );
    Validate( IsEqual( res, mAllTrue ) );
}

//-----------------------------------------------------------------------

SetFunctionName("CompNotEqual");

{
    Soa4Mask3 a( mMixed.y, mMixed.x, CreateSoa4MaskScalar( true, false, false, true ) );
    Soa4Mask3 res = CompNotEqual( a, mMixed );
    Validate( IsEqual( res, mAllTrue ) );

    a = Soa4Mask3( mMixed );
    res = CompNotEqual( a, mMixed );
    Validate( IsEqual( res, mAllFalse ) );
}

//-----------------------------------------------------------------------

SetFunctionName("CompAnyTrue");
{
    Soa4MaskScalar res = CompAnyTrue( mMixed );
    Validate( IsEqual( res, mAllTrue.x ) );
}

//-----------------------------------------------------------------------

SetFunctionName("CompAllTrue");
{
    Soa4MaskScalar res = CompAllTrue( mMixed );
    Validate( IsEqual( res, mAllFalse.x ) );

    res = CompAllTrue( mAllTrue );
    Validate( IsEqual( res, mAllTrue.x ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Select(Soa4MaskScalar::InParam mask, Soa4Mask3::InParam trueValue, Soa4Mask3::InParam falseValue )");
{
    Soa4Mask3 res = Select( mMixed.x, mAllFalse, mAllTrue );
    Soa4Mask3 ref = Soa4Mask3( CreateSoa4MaskScalar( false, true, false, true ), 
        CreateSoa4MaskScalar( false, true, false, true ),
        CreateSoa4MaskScalar( false, true, false, true ) );
    Validate( IsEqual( res, ref ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Select(Soa4Mask3::InParam mask, Soa4Mask3::InParam trueValue, Soa4Mask3::InParam falseValue )");
{
    Soa4Mask3 res = Select( mMixed, mAllFalse, mAllTrue );
    Soa4Mask3 ref = Soa4Mask3( CreateSoa4MaskScalar( false, true, false, true ), 
        CreateSoa4MaskScalar( true, false, true, false ),
        CreateSoa4MaskScalar( true, false, false, true ) );
    Validate( IsEqual( res, ref ) );
}
